#include <stdio.h>
#define GOLD 0
int main(void) {
    int h, m, d;
    if (scanf("%d %d %d", &h, &m, &d) != 3) return 1;
    int total = h * 60 + m + d;
    int clockMinutes = total % 1440;
    printf("arrival=%02d:%02d", clockMinutes / 60, clockMinutes % 60);
#if GOLD
    printf(" days=%d", total / 1440);
#endif
    printf("\n");
    return 0;
}

