collatz-trail.main.c:
#include <stdio.h>
#define GOLD 0
int main(void) {
    long long n, peak;
    int steps = 0;
    if (scanf("%lld", &n) != 1) return 1;
    peak = n;
    while (n != 1) {
        n = n % 2 == 0 ? n / 2 : 3 * n + 1;
        steps++;
        if (n > peak) peak = n;
    }
    printf("steps=%d", steps);
#if GOLD
    printf(" peak=%lld", peak);
#endif
    printf("\n");
    return 0;
}

