#include <stdio.h>
#define GOLD 0
int main(void) {
    int width, height;
    if (scanf("%d %d", &width, &height) != 2) return 1;
    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
#if GOLD
            putchar(y == 0 || x == 0 || y == height-1 || x == width-1 ? '#' : '.');
#else
            putchar('#');
#endif
        }
        putchar('\n');
    }
    return 0;
}

