#include <stdio.h>
#define GOLD 0
int main(void) {
    int n, values[20];
    if (scanf("%d", &n) != 1) return 1;
    for (int i = 0; i < n; i++)
        if (scanf("%d", &values[i]) != 1) return 1;
    int pairs = 0;
#if GOLD
    int longest = 1, streak = 1;
#endif
    for (int i = 1; i < n; i++) {
        if (values[i] == values[i-1]) {
            pairs++;
#if GOLD
            streak++;
#endif
        }
#if GOLD
        else streak = 1;
        if (streak > longest) longest = streak;
#endif
    }
    printf("pairs=%d", pairs);
#if GOLD
    printf(" streak=%d", longest);
#endif
    printf("\n");
    return 0;
}

