#include <stdio.h>
#define GOLD 0
int main(void) {
    char text[31];
    if (scanf("%30s", text) != 1) return 1;
    for (int i = 0; text[i] != '\0'; i++) {
        if (text[i] >= 'a' && text[i] <= 'z')
            text[i] = (char)(text[i] - 'a' + 'A');
#if GOLD
        else if (text[i] >= 'A' && text[i] <= 'Z')
            text[i] = (char)(text[i] - 'A' + 'a');
#endif
    }
    printf("text=%s\n", text);
    return 0;
}

